import { Box, Typography, Button, CircularProgress, Stack } from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { toast } from 'react-hot-toast';
import BaseCard from '../../../components/Cards/Card';
import DisplayChip from '../../../components/DisplayChip';
import {
  setSubscription,
  clearSignupData,
  clearSelectedPlan,
} from '../../../Redux/Slices/AuthSlice';
import { verifyPayment } from '../../../utils/stripeApi';
import { registerUser } from '../../../utils/userApi';

import { APP_STORE_URL } from '../../../constants/signupPlans';

// Persist a completed payment+registration per Stripe session so a page refresh
// restores the success screen instead of re-running registration (which fails
// once signup details have been cleared).
const completionKey = (sessionId) => `payment_success_${sessionId}`;

const StoreBadge = ({
  href,
  src,
  alt,
  height = 44,
  disabled = false,
  iconSrc,
  label,
}) => (
  <Box
    component={disabled ? 'div' : 'a'}
    {...(disabled ? {} : { href, target: '_blank', rel: 'noopener noreferrer' })}
    sx={{
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      bgcolor: '#000',
      borderRadius: '8px',
      overflow: 'hidden',
      lineHeight: 0,
      border: '1px solid rgba(255, 255, 255, 0.35)',
      boxShadow: '0 2px 10px rgba(0, 0, 0, 0.5)',
      cursor: disabled ? 'not-allowed' : 'pointer',
      opacity: disabled ? 0.55 : 1,
      transition: 'transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease',
      ...(disabled
        ? {}
        : {
            '&:hover': {
              transform: 'translateY(-2px)',
              borderColor: 'rgba(255, 255, 255, 0.6)',
              boxShadow: '0 6px 18px rgba(0, 0, 0, 0.6)',
            },
          }),
    }}
  >
    {label ? (
      <Box
        sx={{
          height,
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          px: 2,
        }}
      >
        {iconSrc && (
          <Box
            component="img"
            src={iconSrc}
            alt=""
            sx={{ height: Math.round(height * 0.5), width: 'auto', display: 'block' }}
          />
        )}
        <Typography
          sx={{
            color: 'white',
            fontWeight: 700,
            fontSize: '0.95rem',
            lineHeight: 1,
            whiteSpace: 'nowrap',
          }}
        >
          {label}
        </Typography>
      </Box>
    ) : (
      <Box
        component="img"
        src={src}
        alt={alt}
        sx={{ height, width: 'auto', display: 'block' }}
      />
    )}
  </Box>
);

const formatDate = (unixSeconds) => {
  if (!unixSeconds) return null;
  try {
    return new Date(unixSeconds * 1000).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch (e) {
    return null;
  }
};

const PaymentSuccess = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [searchParams] = useSearchParams();

  const selectedPlan = useSelector((state) => state.auth.selectedPlan);
  const signupData = useSelector((state) => state.auth.signupData);

  const [status, setStatus] = useState('processing'); // processing | success | error
  const [phase, setPhase] = useState('verifying'); // verifying | registering
  const [payment, setPayment] = useState(null);
  const [errorMessage, setErrorMessage] = useState('');
  const [errorAction, setErrorAction] = useState('plans'); // plans | retry-register

  const hasRun = useRef(false);
  const verifiedRef = useRef(null);

  // Step: register the user via the admin add-user endpoint (toggle stays true).
  const runRegistration = useCallback(async () => {
    if (!signupData?.email || !signupData?.password) {
      setStatus('error');
      setErrorAction('plans');
      setErrorMessage(
        'Your signup details were not found. Please start again from signup.',
      );
      return;
    }

    setStatus('processing');
    setPhase('registering');

    try {
      await registerUser({
        name: signupData.fullName,
        email: signupData.email,
        password: signupData.password,
        confirmPassword: signupData.password,
      });

      const sessionId = searchParams.get('session_id');
      if (sessionId && verifiedRef.current) {
        try {
          sessionStorage.setItem(
            completionKey(sessionId),
            JSON.stringify(verifiedRef.current),
          );
        } catch (e) {
          // sessionStorage may be unavailable; non-fatal.
        }
      }

      dispatch(clearSignupData());
      dispatch(clearSelectedPlan());
      setStatus('success');
    } catch (error) {
      setStatus('error');
      setErrorAction('retry-register');
      setErrorMessage(error.message || 'We could not create your account.');
    }
  }, [signupData, dispatch, searchParams]);

  useEffect(() => {
    if (hasRun.current) return;
    hasRun.current = true;

    const sessionId = searchParams.get('session_id');

    if (!sessionId) {
      setStatus('error');
      setErrorAction('plans');
      setErrorMessage('Missing session information. Please try again.');
      return;
    }

    // On refresh, restore the already-completed result instead of re-registering.
    try {
      const cached = sessionStorage.getItem(completionKey(sessionId));
      if (cached) {
        const data = JSON.parse(cached);
        setPayment(data);
        dispatch(setSubscription(data));
        setStatus('success');
        return;
      }
    } catch (e) {
      // Ignore unreadable cache and continue with the normal flow.
    }

    const run = async () => {
      try {
        const data = await verifyPayment({
          sessionId,
          planId: selectedPlan?.planId,
        });

        if (!data?.verified) {
          throw new Error('Payment could not be verified.');
        }

        verifiedRef.current = data;
        setPayment(data);
        dispatch(setSubscription(data));
      } catch (error) {
        setStatus('error');
        setErrorAction('plans');
        setErrorMessage(error.message || 'We could not verify your payment.');
        return;
      }

      await runRegistration();
    };

    run();
  }, [searchParams, selectedPlan, dispatch, runRegistration]);

  const renderProcessing = () => (
    <Stack spacing={3} alignItems="center" sx={{ py: 3 }}>
      <CircularProgress size={56} />
      <Box sx={{ textAlign: 'center' }}>
        <Typography variant="h5" sx={{ color: 'white', mb: 0.5 }}>
          {phase === 'registering'
            ? 'Setting up your account'
            : 'Verifying your payment'}
        </Typography>
        <Typography variant="body2" sx={{ color: 'text.secondary' }}>
          Please wait a moment, this won't take long.
        </Typography>
      </Box>
    </Stack>
  );

  const renderSuccess = () => {
    const renewal = formatDate(payment?.current_period_end);
    let storedPlanLabel = '';
    try {
      storedPlanLabel = sessionStorage.getItem('selectedPlanLabel') || '';
    } catch (e) {
      // sessionStorage may be unavailable; non-fatal.
    }
    const planLabel = storedPlanLabel || selectedPlan?.name || '-';
    const statusLabel = payment?.status || 'active';
    return (
      <Stack spacing={{ xs: 2, sm: 2.25 }} alignItems="center">
        <Box
          sx={{
            position: 'relative',
            width: { xs: 60, sm: 68 },
            height: { xs: 60, sm: 68 },
            borderRadius: '50%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background:
              'radial-gradient(circle at center, rgba(76, 198, 110, 0.22) 0%, rgba(76, 198, 110, 0.06) 65%, transparent 100%)',
            '&::before': {
              content: '""',
              position: 'absolute',
              inset: 0,
              borderRadius: '50%',
              border: '1px solid rgba(76, 198, 110, 0.45)',
              boxShadow: '0 0 26px rgba(76, 198, 110, 0.3)',
            },
          }}
        >
          <CheckCircleIcon
            sx={{
              fontSize: { xs: 38, sm: 44 },
              color: 'primary.main',
              filter: 'drop-shadow(0 4px 12px rgba(76, 198, 110, 0.4))',
            }}
          />
        </Box>

        <Box sx={{ textAlign: 'center', width: '100%' }}>
          <Typography
            variant="h4"
            sx={{
              color: 'white',
              fontWeight: 800,
              lineHeight: 1.2,
              fontSize: { xs: '1.45rem', sm: '1.75rem' },
              mb: 1,
            }}
          >
            Your Account is Ready!
          </Typography>
          <Typography
            variant="body1"
            sx={{
              color: 'text.secondary',
              lineHeight: 1.6,
              maxWidth: 400,
              mx: 'auto',
              mb: 1.25,
              textWrap: 'balance',
            }}
          >
            Your payment is confirmed and your account has been created.
          </Typography>
          <Typography
            variant="body1"
            sx={{
              color: 'text.secondary',
              lineHeight: 1.6,
              maxWidth: 400,
              mx: 'auto',
              textWrap: 'balance',
            }}
          >
            Download the app and log in using the{' '}
            <Box component="span" sx={{ color: 'white', fontWeight: 600 }}>
              same email and password
            </Box>{' '}
            you entered at signup.
          </Typography>
        </Box>

        {payment && (
          <Box
            sx={{
              width: '100%',
              p: { xs: 1.5, sm: 2 },
              borderRadius: '14px',
              border: '1px solid rgba(255, 255, 255, 0.1)',
              bgcolor: 'rgba(255, 255, 255, 0.03)',
            }}
          >
            <Stack divider={<Box sx={{ height: '1px', bgcolor: 'rgba(255, 255, 255, 0.06)' }} />} spacing={1.25}>
              <Stack
                direction="row"
                justifyContent="space-between"
                alignItems="center"
                spacing={2}
              >
                <Typography variant="body2" sx={{ color: 'text.secondary', flexShrink: 0 }}>
                  Plan
                </Typography>
                <Typography variant="body2" sx={{ color: 'white', fontWeight: 600 }}>
                  {planLabel}
                </Typography>
              </Stack>
              <Stack
                direction="row"
                justifyContent="space-between"
                alignItems="center"
                spacing={2}
              >
                <Typography variant="body2" sx={{ color: 'text.secondary', flexShrink: 0 }}>
                  Status
                </Typography>
                <DisplayChip
                  label={statusLabel.toUpperCase()}
                  size="small"
                  sx={{
                    bgcolor: 'rgba(76, 198, 110, 0.15)',
                    color: 'primary.main',
                    fontWeight: 700,
                    fontSize: '0.65rem',
                    letterSpacing: '0.05em',
                  }}
                />
              </Stack>
              {payment.customer_email && (
                <Stack
                  direction="row"
                  justifyContent="space-between"
                  alignItems="flex-start"
                  spacing={2}
                >
                  <Typography variant="body2" sx={{ color: 'text.secondary', flexShrink: 0 }}>
                    Email
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      color: 'white',
                      fontWeight: 600,
                      textAlign: 'right',
                      wordBreak: 'break-all',
                      minWidth: 0,
                    }}
                  >
                    {payment.customer_email}
                  </Typography>
                </Stack>
              )}
              {renewal && (
                <Stack
                  direction="row"
                  justifyContent="space-between"
                  alignItems="center"
                  spacing={2}
                >
                  <Typography variant="body2" sx={{ color: 'text.secondary', flexShrink: 0 }}>
                    {statusLabel === 'trialing' ? 'Trial ends' : 'Renews on'}
                  </Typography>
                  <Typography variant="body2" sx={{ color: 'white', fontWeight: 600 }}>
                    {renewal}
                  </Typography>
                </Stack>
              )}
            </Stack>
          </Box>
        )}

        <Box sx={{ width: '100%' }}>
          <Typography
            variant="caption"
            sx={{
              display: 'block',
              textAlign: 'center',
              color: 'text.secondary',
              mb: 1,
              letterSpacing: '0.04em',
            }}
          >
            GET THE APP
          </Typography>
          <Stack
            direction="row"
            spacing={1.5}
            justifyContent="center"
            alignItems="center"
            sx={{ width: '100%' }}
          >
            <StoreBadge
              href={APP_STORE_URL}
              src="/badges/app-store.svg"
              alt="Download on the App Store"
            />
            {/* Google Play button is hidden until the Android app is published.
                To re-enable: restore the PLAY_STORE_URL constant at the top of this
                file and uncomment the StoreBadge below (and remove the note further down).
            <StoreBadge
              href={PLAY_STORE_URL}
              src="/badges/google-play.svg"
              alt="Get it on Google Play"
            />
            */}
          </Stack>

          {APP_STORE_URL && APP_STORE_URL !== '#' && (
            <Typography
              variant="caption"
              sx={{
                display: 'block',
                textAlign: 'center',
                color: 'text.secondary',
                mt: 1.25,
              }}
            >
              OR click here to {' '}
              <Box
                component="a"
                href={APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
                sx={{
                  color: 'primary.main',
                  fontWeight: 600,
                  textDecoration: 'underline',
                  textUnderlineOffset: '2px',
                  '&:hover': { color: 'primary.light' },
                }}
              >
                Download
              </Box>
            </Typography>
          )}

          <Stack
            direction="row"
            spacing={0.75}
            justifyContent="center"
            alignItems="center"
            sx={{ mt: 1.25 }}
          >
            <Box
              component="img"
              src="/badges/google-play-icon.svg"
              alt=""
              sx={{ height: 14, width: 'auto', opacity: 0.5, filter: 'grayscale(1)' }}
            />
            <Typography
              variant="caption"
              sx={{ color: 'text.secondary', letterSpacing: '0.02em' }}
            >
              Android app  coming soon on Google Play
            </Typography>
          </Stack>
        </Box>
      </Stack>
    );
  };

  const renderError = () => (
    <Stack spacing={3} alignItems="center">
      <Box
        sx={{
          width: 88,
          height: 88,
          borderRadius: '50%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          bgcolor: 'rgba(255, 68, 68, 0.12)',
          border: '1px solid rgba(255, 68, 68, 0.4)',
        }}
      >
        <ErrorOutlineIcon sx={{ fontSize: 56, color: 'error.main' }} />
      </Box>

      <Box sx={{ textAlign: 'center' }}>
        <Typography variant="h4" sx={{ color: 'white', fontWeight: 800, mb: 1 }}>
          {errorAction === 'retry-register'
            ? 'Account Setup Failed'
            : 'Verification Failed'}
        </Typography>
        <Typography variant="body1" sx={{ color: 'text.secondary' }}>
          {errorMessage}
        </Typography>
        {errorAction === 'retry-register' && (
          <Typography variant="body2" sx={{ color: 'text.secondary', mt: 1 }}>
            Your payment was successful  you can safely retry creating your account.
          </Typography>
        )}
      </Box>

      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ width: '100%' }}>
        {errorAction === 'retry-register' ? (
          <Button
            fullWidth
            variant="contained"
            size="large"
            onClick={() => {
              toast.dismiss();
              runRegistration();
            }}
          >
            Retry
          </Button>
        ) : (
          <Button fullWidth variant="outlined" size="large" onClick={() => navigate('/app-plans')}>
            Back to Plans
          </Button>
        )}
      </Stack>
    </Stack>
  );

  return (
    <Box
      sx={{
        width: '100%',
        display: 'flex',
        justifyContent: 'center',
        px: { xs: 1.5, sm: 0 },
      }}
    >
      <BaseCard
        maxWidth={460}
        sx={{
          width: '100%',
          maxWidth: 460,
          p: { xs: 3, sm: 4 },
          mt: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.7)',
          backdropFilter: 'blur(16px)',
          border: '1px solid #4CC66E',
          borderRadius: '16px',
          boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.8)',
        }}
      >
        {status === 'processing' && renderProcessing()}
        {status === 'success' && renderSuccess()}
        {status === 'error' && renderError()}
      </BaseCard>
    </Box>
  );
};

export default PaymentSuccess;
