import { apiFetch } from './apiClient';

const parseJson = async (response) => {
  const json = await response.json().catch(() => ({}));
  if (!response.ok || json?.error) {
    const error = new Error(
      json?.message || json?.message_en || `Request failed: ${response.status}`,
    );
    error.status = response.status;
    error.data = json;
    throw error;
  }
  return json;
};

// Public v2 endpoint  pay-first-then-register flow (no JWT required).
export const createCheckoutSession = async (payload) => {
  const body = {
    mode: payload.mode || 'subscription',
    quantity: payload.quantity || 1,
    trial_days: payload.trialDays ?? 7,
    success_url: payload.successUrl,
    cancel_url: payload.cancelUrl,
    ...(payload.lookupKey ? { lookup_key: payload.lookupKey } : {}),
    ...(payload.priceId ? { price_id: payload.priceId } : {}),
    ...(payload.planId ? { plan_id: payload.planId } : {}),
    ...(payload.customerEmail ? { email: payload.customerEmail } : {}),
  };

  const response = await apiFetch('/stripe/v2/create-session', null, {
    method: 'POST',
    body,
  });
  const json = await parseJson(response);
  return json.data;
};

// Public v2 endpoint  returns flat payment details needed for registration.
export const verifyPayment = async ({ sessionId, planId }) => {
  const response = await apiFetch('/stripe/v2/verify', null, {
    method: 'POST',
    body: {
      session_id: sessionId,
      ...(planId ? { plan_id: planId } : {}),
    },
  });
  const json = await parseJson(response);
  return json.data || null;
};
